"""Build a source-linked visual gallery without changing source paragraph anchors."""
from pathlib import Path
import json,html,zipfile
ROOT=Path(__file__).resolve().parents[1];SITE=ROOT/'site';OUT=SITE/'previews/aru/story-stages';OUT.mkdir(parents=True,exist_ok=True)
d=json.loads((ROOT/'sources/aru-story-stages.json').read_text());blocks={b['id']:b['text'] for b in json.loads((SITE/'content/stories-p01889.json').read_text())['blocks']};e=html.escape
cards=[]
for i,s in enumerate(d['stages'],1):
 assert s['quote'] in blocks[s['blockId']],s['id']
 assert (SITE/s['image']).is_file(),s['image']
 cards.append(f'''<article id="{e(s['id'])}" class="stage"><div class="image"><a href="{e(s['id'])}.png" download><img src="{e(s['id'])}.png" alt="Aru: {e(s['title'])}" width="256" height="256" loading="lazy"></a></div><div><p class="eyebrow">Recorded moment {i} · visual interpretation</p><h2>{e(s['title'])}</h2><p class="when">{e(s['when'])}</p><p>{e(s['summary'])}</p><blockquote>{e(s['quote'])}</blockquote><a href="../../../{e(s['sourceHref'])}">Read the supporting passage →</a><p class="note">{e(s['artNote'])}</p><a href="{e(s['id'])}.png" download>Download transparent PNG</a></div></article>''')
css='''*{box-sizing:border-box}body{margin:0;background:#14111c;color:#eee7ff;font:16px system-ui}main{max-width:1080px;margin:auto;padding:28px 20px}a{color:#a9e5e5}nav,.links{display:flex;gap:18px;flex-wrap:wrap;margin:20px 0}h1{font-size:clamp(30px,5vw,48px)}h2{font-size:25px;margin:8px 0}p{line-height:1.65;color:#d4cadf}.eyebrow{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#c5a8ef}.notice{border-left:3px solid #b3a2de;padding:4px 20px;background:#211b2c}.stage{display:grid;grid-template-columns:300px 1fr;gap:28px;padding:34px 0;border-top:1px solid #463852}.image{display:flex;align-items:center;justify-content:center;background:#0d0b13;border-radius:16px}.image img{width:100%;max-width:300px;height:auto;image-rendering:pixelated}.when{font-weight:600;color:#e4cc91}.note{font-size:14px;color:#aaa0ba}blockquote{margin:18px 0;border-left:2px solid #6c5e80;padding:0 18px;color:#ddd5e8;line-height:1.6}.concept{border:1px dashed #78618b;padding:24px;border-radius:12px;margin:35px 0}.layers{position:relative;max-width:420px;aspect-ratio:1;margin:20px auto;background:#0d0b13}.layers img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;image-rendering:pixelated}.milestones{padding:20px;background:#211b2c;border-radius:12px}@media(max-width:650px){.stage{grid-template-columns:1fr;gap:15px}.image{min-height:256px}.image img{max-width:256px}}'''
concept=d['laterConcept'];page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(d['title'])}</title><style>{css}</style></head><body><main><nav><a href="../../../wiki.html#topic-19f4c798b156">Aru’s profile</a><a href="../../../wiki.html#topic-10461a4ed91a">House of First Continuities & Adaptive Nursery</a><a href="../../../index.html#read=stories-p01889">Read The First Newborn</a></nav><p class="eyebrow">Story-grounded visual studies · PixelLab</p><h1>{e(d['title'])}</h1><div class="notice"><p>{e(d['scope'])}</p><p>{e(d['artNotice'])}</p></div><div class="links"><a href="aru-story-stages.zip" download>Download all six transparent images</a><a href="stages.json" download>Stage notes & source links</a><a href="{e(d['sourceUrl'])}">Original Google Doc</a></div>{''.join(cards)}<section class="milestones"><h2>Development is more than a change of shape</h2><p>Between these moments, Aru develops shared signs, chooses a public name, questions who has authority over its identity, and wins the right to remain unfinished. Those events do not supply separate fixed costumes or biological ages.</p><div class="links"><a href="../../../index.html#read=stories-p01889&block=stories-p02253">Choosing the name Aru</a><a href="../../../index.html#read=stories-p01889&block=stories-p02550">The right to remain unfinished</a><a href="../../../index.html#read=stories-p01889&block=stories-p02619">Ownership of the saved copy</a></div></section><section class="concept" id="later-concept"><p class="eyebrow">{e(concept['status'])}</p><h2>{e(concept['title'])}</h2><p>{e(concept['note'])}</p><div class="layers"><img src="later-galaxy-background.png" alt="Galaxy backdrop from the separate earlier concept" loading="lazy"><img src="later-winged-concept.png" alt="Earlier winged Aru concept, undated and outside the recorded story stages" loading="lazy"></div><div class="links"><a href="later-winged-concept.png" download>Earlier character layer</a><a href="later-galaxy-background.png" download>Separate galaxy layer</a><a href="../color-orbit-v2/">Degraded chapel concept</a></div></section><p class="note">Source checked against the connected story document on {e(d['verifiedDate'])}. The numbered moments organize this gallery; they are not assigned era transitions or a claim of a complete lifespan.</p></main></body></html>'''
(OUT/'index.html').write_text(page);(OUT/'stages.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
(OUT/'README.txt').write_text(d['scope']+'\n\n'+d['artNotice']+'\n\n'+ '\n\n'.join(s['title']+'\n'+s['summary']+'\nSource: https://ragingaxolotl-art.github.io/cyber-pet-lore/'+s['sourceHref']+'\nArt note: '+s['artNote'] for s in d['stages'])+'\n\n'+concept['note']+'\n')
with zipfile.ZipFile(OUT/'aru-story-stages.zip','w',zipfile.ZIP_DEFLATED) as z:
 for s in d['stages']:z.write(SITE/s['image'],s['id']+'.png')
 for name in ['stages.json','README.txt']:z.write(OUT/name,name)
print('Aru story gallery: six verified source passages and six visual studies')
